function readableSourceSummary(ability){const raw=String(ability?.desc||ability?.mechanics?.sourceText||'').replace(/\s+/g,' ').trim(),sentences=raw.split(/(?<=[.!?])\s+(?=[A-ZÀ-Ÿ])/).map(s=>s.replace(/^(?:Le personnage|Le sorcier|Le moine|Le forgesort|Le magicien|L’ensorceleur|Le rôdeur|Le voleur|Le barde|Le prêtre|Le druide|Le guerrier|Le chevalier|Le barbare) peut /,'Peut ').replace(/un bonus de /g,'').replace(/mètres/g,'m').replace(/une fois par /gi,'1 fois par ').replace(/\s+/g,' ').trim()).filter(s=>s&&!/^(?:Note|Et sur les Terres|PROFIL HYBRIDE|GÉRER|PARTICULARITÉS)/.test(s));if(!sentences.length)return '';if(sentences.join(' ').length<=260)return sentences.join(' ');const scored=sentences.map((text,index)=>({text,index,score:(/\b(?:DM|PV|PM|DEF|Initiative|attaque|soign|dé bonus|dé malus|immun|déplace|déplacement|choisit|permet|réduit|divise)\b/i.test(text)?4:0)+(index===0?3:0)})).filter(x=>x.text.length<=260).sort((a,b)=>b.score-a.score||a.index-b.index),chosen=[];for(const item of scored){if(chosen.reduce((n,x)=>n+x.text.length+1,0)+item.text.length<=260)chosen.push(item);}return chosen.length?chosen.sort((a,b)=>a.index-b.index).map(x=>x.text).join(' '):sentences[0];}
